function relv(k){return Math.max(0,Math.min(100,(G.st[k]||0)+({rMind:40,rTon:30,rPar:60})[k]))}
function relRow(){const R=[];if(G.f.mind)R.push(['มายด์','rMind']);if(G.f.g1||G.f.ton)R.push(['ต้น','rTon']);R.push(['พ่อแม่','rPar']);return `<div class="st-rel">${R.map(([n,k])=>{const v=relv(k);return `<span><small>${n}</small><i><u style="width:${v}%"></u></i></span>`}).join('')}</div>`}
function curDream(){const r=(G.refl||[]).filter(x=>x.nd);return r.length?r.at(-1).nd:(G.letter||'ยังไม่รู้')}
function vReflect(s){const lb=txt(RFL[s.per]);G.rf=G.rf||{};const st=G.rf[s.id]||{};
 if(!st.mDone){const L=(G.log||[]).filter(e=>e&&e.p&&RFP[s.per].includes(e.p)&&e.t);const seen={};const pick=L.filter(e=>/^[euw]-/.test(e.id)).concat(L.filter(e=>!/^[euw]-/.test(e.id)&&!/^0\./.test(e.id))).filter(e=>seen[e.t]?false:(seen[e.t]=1)).slice(0,5);st.list=pick.map(e=>e.t);G.rf[s.id]=st;
  return `<section class="st-card st-story"><small>ช่วงสะท้อนตัวเอง · ${lb}</small><p>ปีนี้ผ่านไปแล้ว ลองมองย้อนกลับไป</p><h3 class="st-q">เรื่องไหนทำให้เธอรู้จักตัวเองมากขึ้นที่สุด</h3><div class="st-op">${st.list.map((t,j)=>`<button data-st="rfm" data-v="${j}"><i>${j+1}</i><b>${esc(t)}</b></button>`).join('')}<button data-st="rfm" data-v="-1"><i>·</i><b>ไม่มีเรื่องไหนเป็นพิเศษ</b></button></div></section>`}
 if(st.d==null)return `<section class="st-card st-story"><small>ช่วงสะท้อนตัวเอง · ${lb}</small><h3 class="st-q">ตอนนี้ยังอยากเป็น "${esc(curDream())}" อยู่ไหม</h3><div class="st-op"><button data-st="rfd" data-v="0"><i>1</i><b>ยังอยากเหมือนเดิม</b></button><button data-st="rfd" data-v="1"><i>2</i><b>เริ่มไม่แน่ใจ</b></button><button data-st="rfd" data-v="2"><i>3</i><b>เปลี่ยนไปแล้ว</b></button></div></section>`;
 return `<section class="st-card st-story"><small>ช่วงสะท้อนตัวเอง · ${lb}</small><h3 class="st-q">ตอนนี้อยากเป็นอะไร</h3><input id="st-nd" class="st-in" maxlength="60" placeholder="พิมพ์สั้น ๆ หรือ ยังไม่รู้"><button class="ls-go" data-st="rfn">บันทึกแล้วไปต่อ</button></section>`}
function finishReflect(s,nd){const st=G.rf[s.id];G.refl=G.refl||[];G.refl.push({per:s.per,lb:txt(RFL[s.per]),m:st.m,d:st.d,nd:nd||null,prev:curDream()});next()}
/* epilogue */
const JOBCODE=G=>{const j=G.job;if(!j)return '';const f=G.fac!=null?FAC[G.fac]:null;return {A:f?f[1]:'E',B:'EC',C:'CS',D:f?f[1]:'E',E:'E',F:f?f[1]:'A',G:'CS',H:f?f[1]:'I',I:'I'+(f?f[1][0]:'A'),J:'RS',K:f?f[1]:'A'}[j.k]||''};
function epiText(){const v=valAll(G),vt=top2(v),it=top2(interest(G)),jc=JOBCODE(G);const valFit=G.job&&G.job.v===vt[0]?2:G.job&&vt.slice(0,2).includes(G.job.v)?1:0;const intFit=jc&&it.slice(0,2).some(k=>jc.slice(0,2).includes(k))?1:0;const co=top2(G.cope)[0];const L=[];
 L.push(`อีก 5 ปีต่อมา เธออายุ ${G.f.workfirst?23:27} ปี`);
 if(valFit>=1&&intFit)L.push(`งาน${esc(G.job.t)}ยังทำให้เธออยากตื่นไปทำงาน เพราะมันตรงทั้งกับสิ่งที่ชอบ (${DIR[it[0]]}) และสิ่งที่ให้ค่า (${VAL[vt[0]]})`);
 else if(intFit)L.push(`เนื้องานสนุกและถนัด แต่ราวปีที่สาม เธอเริ่มรู้สึกว่า${VAL[vt[0]]}ที่เคยให้ค่ามากที่สุดหายไปจากชีวิต เธอเลยเริ่มมองหาทางเติมสิ่งนั้นกลับมา`);
 else if(valFit>=1)L.push(`งานให้${VAL[G.job.v]}อย่างที่ต้องการ แต่เนื้องานไม่ใช่สิ่งที่ชอบ เธอเลยหาทางได้ใช้ด้าน${DIR[it[0]]}นอกเวลางาน ซึ่งช่วยให้ทุกอย่างสมดุลขึ้น`);
 else L.push(`ราวปีที่สาม เธอเริ่มรู้สึกว่างเปล่ากับงาน ทั้งที่ทุกอย่างดูโอเค วันหนึ่งเธอตัดสินใจลงเรียนคอร์สด้าน${DIR[it[0]]} และเริ่มคิดเรื่องเปลี่ยนทาง ซึ่งไม่ได้สายเกินไปเลย`);
 L.push(co==='alone'?'บางช่วงงานหนักจนเหนื่อย และเธอยังเก็บความรู้สึกไว้คนเดียวเหมือนเคย จนวันหนึ่งได้เรียนรู้ว่าการขอความช่วยเหลือไม่ใช่ความอ่อนแอ':co==='help'?'วันที่เหนื่อย เธอรู้เสมอว่าจะคุยกับใคร':co==='rest'?'เธอรู้จักพักเมื่อถึงเวลา และกลับมาได้ทุกครั้ง':'เวลามีปัญหา เธอยังเป็นคนที่ลงมือแก้ก่อนใคร');
 if(G.f.mind)L.push(relv('rMind')>=60?'มายด์ยังเป็นคนแรกที่เธอโทรหาเวลามีข่าวดี':relv('rMind')>=35?'เธอกับมายด์ยังทักหากันวันเกิด':'เธอกับมายด์ห่างกันไป บางคืนเธอยังนึกถึงโต๊ะประจำที่โรงอาหาร');
 if(G.f.ton&&relv('rTon')>=60)L.push(G.f.tonArc==='stay'?'ต้นเรียนจบแล้ว และยังพูดถึงวันที่เธอช่วยหาทุนให้เสมอ':'ต้นกลายเป็นเพื่อนที่เธอไว้ใจที่สุดคนหนึ่ง');
 L.push(relv('rPar')>=65?'พ่อแม่ภูมิใจในทางที่เธอเลือก ถึงจะไม่ตรงกับที่เคยคิดไว้ทั้งหมด':relv('rPar')>=40?'เธอกับพ่อแม่ยังคุยกันเรื่องอนาคตอยู่เรื่อย ๆ':'เธอกับพ่อแม่ยังมีเรื่องที่ไม่เข้าใจกัน แต่ระยะห่างก็ทำให้ทั้งสองฝ่ายได้ฟังกันมากขึ้น');
 return L}
function vEpi(){const L=epiText();return `<section class="st-card st-story st-epi"><small>บทส่งท้าย · อีก 5 ปีต่อมา</small>${L.map(l=>`<p>${l}</p>`).join('')}<p class="st-note">นี่เป็นแค่หนึ่งในความเป็นไปได้ ไม่ใช่การทำนายอนาคต</p><button class="ls-go" data-st="next">เปิดแฟ้มค้นหาตัวเอง</button></section>`}
/* consistency */
function cons(h){if(!h||h.length<3)return null;const c={};h.forEach(k=>c[k]=(c[k]||0)+1);const t=Object.entries(c).sort((a,b)=>b[1]-a[1])[0];const r=t[1]/h.length;return {k:t[0],r,n:h.length,lb:r>=.55?'ชัดเจน':r>=.38?'ค่อนข้างชัด':'ยังเปลี่ยนไปตามสถานการณ์'}}
function consChip(c){return c?`<span class="st-cc ${c.r>=.55?'hi':c.r>=.38?'md':'lo'}">${c.lb} · ${c.n} สถานการณ์</span>`:''}
function intCons(){const s=top2(survPct(G))[0],c=top2(choicePct(G));return s===c[0]?'ชัดเจน':c.slice(0,2).includes(s)?'ค่อนข้างชัด':'ยังไม่ตรงกัน'}
function quickSec(){const q=G.quick||[];if(!q.length)return '';const ms=q.filter(x=>x.ms<10000).map(x=>x.ms);const av=ms.length?ms.reduce((a,b)=>a+b,0)/ms.length/1000:10;const to=q.length-ms.length;
 return `<section class="st-card"><h3>ปฏิกิริยาแรกของฉัน</h3><p class="st-t">ในสถานการณ์ที่ต้องตัดสินใจภายใน 10 วินาที เธอใช้เวลาเฉลี่ย <b>${av.toFixed(1)} วินาที</b>${to?` และนิ่งไปจนหมดเวลา ${to} ครั้ง`:''} · ${av<4?'เธอตัดสินใจเร็วจากสัญชาตญาณ':av<7?'เธอคิดสักพักก่อนตัดสินใจ':'เธอชั่งน้ำหนักนานก่อนลงมือ ซึ่งบางครั้งทำให้สถานการณ์ผ่านไปก่อน'}</p>${q.map(x=>`<div class="st-mo"><small>${x.ms<10000?(x.ms/1000).toFixed(1)+' วินาที':'หมดเวลา'}</small><b>${esc(x.t)}</b><span>${esc(x.c)}</span></div>`).join('')}</section>`}
function relSec(){const R=[];const msg=(k,hi,md,lo)=>relv(k)>=60?hi:relv(k)>=35?md:lo;
 if(G.f.mind)R.push(['มายด์',msg('rMind','"ขอบคุณที่ทักเราก่อนวันนั้นนะ ไม่งั้นเราคงไม่มีเพื่อนสนิทแบบแก"','"ถึงช่วงหลังเราจะห่างกันไปบ้าง แต่เรายังจำโต๊ะประจำที่โรงอาหารได้"','"เราเสียดายที่ไม่ได้คุยกันให้เคลียร์ ถ้าวันไหนว่าง ทักมานะ"'),relv('rMind')]);
 if(G.f.g1||G.f.ton)R.push(['ต้น',msg('rTon','"วันที่แกทักมาถามว่าเราเป็นอะไร เราไม่เคยลืมเลย"','"ตอนนั้นเราอาจไม่ค่อยดีกับแก แต่เราโตขึ้นแล้วนะ"','"ขอโทษเรื่องตอน ม.4 นะ ตอนนั้นเราแย่จริง ๆ"'),relv('rTon')]);
 R.push(['พ่อแม่',msg('rPar','"พ่อกับแม่ภูมิใจในตัวลูก ไม่ว่าลูกจะเลือกทางไหน"','"เราอาจคิดไม่เหมือนกันทุกเรื่อง แต่เราอยู่ข้างลูกเสมอ"','"พ่อแม่อาจพูดน้อยไป แต่อยากให้ลูกรู้ว่าเราเป็นห่วง"'),relv('rPar')]);
 return `<section class="st-card"><h3>ข้อความจากคนสำคัญ</h3>${R.map(([n,t,v])=>`<div class="st-msg"><div><b>${n}</b><i><u style="width:${v}%"></u></i></div><p>${esc(t)}</p></div>`).join('')}</section>`}
function dreamSec(){const r=G.refl||[];if(!r.length)return '';const D=['ยังอยากเหมือนเดิม','เริ่มไม่แน่ใจ','เปลี่ยนไปแล้ว'];
 return `<section class="st-card"><h3>ความฝันที่เปลี่ยนไป</h3><div class="st-dr"><div><small>คืนก่อนเปิดเทอม ม.4</small><b>${esc(G.letter||'ยังไม่รู้')}</b></div>${r.map(x=>`<div><small>${esc(x.lb)} · ${D[x.d]}</small><b>${esc(x.nd||x.prev)}</b>${x.m?`<span>เรื่องที่ทำให้รู้จักตัวเอง: ${esc(x.m)}</span>`:''}</div>`).join('')}</div></section>`}

