function moodNow(){const m=(G.moods||[]).slice(-3);if(!m.length)return 0;return m.reduce((a,x)=>a+x.v,0)/m.length}
function heartWord(){const sc=moodNow()*1.5-((G.st.stress||0)-2)*.6;return sc>=1.5?'สดใส':sc>=0?'ปกติดี':sc>=-1.5?'เหนื่อยนิด ๆ':'หนักใจ'}
function moodCls(){const m=moodNow();return m>=1?'mood-hi':m<=-1?'mood-lo':''}
