function moodGraph(){const m=G.moods||[];if(m.length<2)return '';const W=320,H=120,X=i=>16+i*(W-32)/(m.length-1),Y=v=>H/2-v*(H/2-14)/2;const d=m.map((x,i)=>(i?'L':'M')+X(i).toFixed(1)+' '+Y(x.v).toFixed(1)).join('');const cnt={};m.forEach(x=>x.em.forEach(e=>cnt[e]=(cnt[e]||0)+1));const top=Object.entries(cnt).sort((a,b)=>b[1]-a[1]).slice(0,3).map(x=>x[0]);const hi=m.reduce((a,b)=>b.v>a.v?b:a),lo=m.reduce((a,b)=>b.v<a.v?b:a);
 return `<section class="st-card"><h3>กราฟใจตลอดเส้นทาง</h3><svg class="st-mg" viewBox="0 0 ${W} ${H}" aria-label="กราฟความรู้สึก"><line x1="10" x2="${W-10}" y1="${H/2}" y2="${H/2}" stroke="#F4DDE0" stroke-dasharray="3 3"/><path d="${d}" fill="none" stroke="#E31414" stroke-width="2.4" stroke-linejoin="round"/>${m.map((x,i)=>`<circle cx="${X(i).toFixed(1)}" cy="${Y(x.v).toFixed(1)}" r="4" fill="#fff" stroke="#E31414" stroke-width="2"/>`).join('')}</svg><p class="st-t">ใจขึ้นสูงสุดตอน <b>${esc(hi.t)}</b> และลงต่ำสุดตอน <b>${esc(lo.t)}</b> · ความรู้สึกที่มาบ่อยที่สุดคือ <b>${top.join(' · ')}</b></p></section>`}
function voiceSec(){const v=G.voices||[];if(!v.length)return '';const c={};v.forEach(x=>c[x.s]=(c[x.s]||0)+1);const t=Object.entries(c).sort((a,b)=>b[1]-a[1])[0][0];return `<section class="st-card"><h3>เสียงในหัวของฉัน</h3><p class="st-t">เวลาเจอเรื่องหนัก เสียงที่ดังที่สุดคือ <b>${VSTN[t]}</b> · ${VSTD[t]}</p>${v.map(x=>`<div class="st-mo"><small>${PER[x.p]||''}</small><b>${esc(x.t)}</b><span>“${esc(x.c)}”</span></div>`).join('')}</section>`}
function unsentSec(){const u=(G.unsent||[]).filter(x=>x.text);if(!u.length)return '';return `<section class="st-card"><h3>ข้อความที่ไม่ได้ส่ง</h3><p class="st-note">เห็นได้แค่เธอคนเดียว</p>${u.map(x=>`<div class="st-un"><small>${esc(x.to)}</small><p>${esc(x.text)}</p></div>`).join('')}</section>`}
