/* ---------- deeper high-school life: traits, people, scenes, events ---------- */
const AX=[['tHead','tHeart','ใช้เหตุผล','ใช้ความรู้สึก','เวลาตัดสินใจ'],['tIn','tOut','ชาร์จพลังคนเดียว','ชาร์จพลังกับผู้คน','พลังงานของฉัน'],['tIntr','tExtr','ทำเพราะอยากทำ','ทำเพื่อเป้าหมายภายนอก','แรงจูงใจ'],['tSafe','tBold','เลือกทางที่มั่นใจ','กล้าลองสิ่งใหม่','ความเสี่ยง'],['tPlan','tFlow','วางแผนล่วงหน้า','ปรับไปตามสถานการณ์','จังหวะชีวิต'],['tStuck','tGrow','ล้มแล้วโทษตัวเอง','ล้มแล้วหาบทเรียน','เวลาผิดพลาด'],['tOthr','tSelf','ฟังเสียงคนรอบข้าง','ฟังเสียงตัวเอง','เวลาเลือกทางชีวิต']];
const TRX={};AX.forEach(a=>{TRX[a[0]]=1;TRX[a[1]]=1});
const RELB={rMind:40,rTon:30,rPar:60,rPo:25,rBeam:30,rSib:50};
function relv(k){return Math.max(0,Math.min(100,(G.st[k]||0)+(RELB[k]||40)))}
function sibName(){return G.f.sib==='old'?'พี่':G.f.sib==='young'||G.f.sib==='both'?'น้อง':null}
function relRow(){if(G.mode==='sw')return relRowSW();const R=[];if(G.f.mind)R.push(['มายด์','rMind']);if(G.f.g1||G.f.ton)R.push(['ต้น','rTon']);if(G.f.newkid)R.push(['ปอ','rPo']);if(G.f.beamMet)R.push(['พี่บีม','rBeam']);if(sibName())R.push([sibName(),'rSib']);R.push(['พ่อแม่','rPar']);
 return `<div class="st-rel${R.length>3?' many':''}">${R.map(([n,k])=>{const v=relv(k);return `<span><small>${n}</small><i><u style="width:${v}%"></u></i></span>`}).join('')}</div>`}
const _relSecBase=relSec;
function relSecX(){const msg=(k,hi,md,lo)=>relv(k)>=60?hi:relv(k)>=35?md:lo;const X=[];
 if(G.f.newkid)X.push(['ปอ',msg('rPo','"ถ้าวันนั้นเธอไม่ชวนเรากินข้าว เราคงลาออกไปแล้ว"','"ขอบคุณที่เคยใจดีกับเด็กใหม่อย่างเรานะ"','"เราอาจไม่ได้สนิทกัน แต่เรายังจำรอยยิ้มวันแรกได้"'),relv('rPo')]);
 if(G.f.beamMet)X.push(['พี่บีม',msg('rBeam','"พี่ดีใจที่ได้เห็นน้องเลือกทางของตัวเองนะ"','"มีอะไรทักพี่มาได้เสมอ"','"ขอให้น้องเจอทางที่ใช่นะ"'),relv('rBeam')]);
 if(sibName())X.push([sibName(),msg('rSib',G.f.sib==='old'?'"แกโตขึ้นเยอะเลยนะ พี่ภูมิใจ"':'"โตขึ้นอยากเป็นแบบพี่"','"ถึงจะทะเลาะกันบ่อย แต่ก็รักนะ"','"ช่วงนี้ไม่ค่อยได้คุยกันเลย คิดถึงนะ"'),relv('rSib')]);
 const h=_relSecBase();if(!X.length)return h;return h.replace('</section>',X.map(([n,t,v])=>`<div class="st-msg"><div><b>${n}</b><i><u style="width:${v}%"></u></i></div><p>${esc(t)}</p></div>`).join('')+'</section>')}
/* traits summary for file */
function trPos(a){const l=(G.tr||{})[a[0]]||0,r=(G.tr||{})[a[1]]||0;return {l,r,p:(r-l)/(l+r+2),n:l+r}}
function trTop(n){return AX.map(a=>({a,...trPos(a)})).filter(x=>x.n>=2).sort((x,y)=>Math.abs(y.p)-Math.abs(x.p)).slice(0,n)}
const TRS={tHead:'เวลาต้องตัดสินใจ เธอมักหยุดคิดถึงเหตุผลและข้อมูลก่อนเสมอ',tHeart:'เวลาต้องตัดสินใจ เธอฟังความรู้สึกของตัวเองและของคนรอบข้างก่อนเหตุผล',tIn:'เธอชาร์จพลังจากความเงียบ ช่วงเวลาที่ได้อยู่กับตัวเองคือที่ที่เธอกลับมาเป็นตัวเองเต็มที่',tOut:'เธอมีพลังที่สุดตอนได้อยู่กับผู้คน เสียงหัวเราะของเพื่อนคือแบตเตอรี่ของเธอ',tIntr:'สิ่งที่ผลักเธอไปข้างหน้าคือความอยากรู้และความอยากทำ ไม่ใช่คำชมหรือคะแนน',tExtr:'เธอมีแรงที่สุดเมื่อมีเป้าหมายชัด ๆ ให้ไปถึง และอยากให้ความพยายามของตัวเองถูกมองเห็น',tSafe:'เธอเลือกก้าวที่มั่นคงก่อนเสมอ ซึ่งทำให้คนรอบตัวไว้ใจเธอได้',tBold:'เธอกล้าก้าวไปในที่ที่ยังไม่รู้จัก แม้ใจจะเต้นแรงก็ตาม',tPlan:'เธอชอบรู้ว่าพรุ่งนี้จะเกิดอะไร แผนที่ดีทำให้ใจเธอสงบ',tFlow:'เธอปรับตัวไปตามสถานการณ์ได้เก่ง ทางที่ไม่ได้วางไว้ไม่ทำให้เธอกลัว',tStuck:'เวลาผิดพลาด เธอมักโทษตัวเองหนักกว่าที่ควร ลองใจดีกับตัวเองให้เท่ากับที่ใจดีกับคนอื่น',tGrow:'เวลาผิดพลาด เธอไม่หยุดอยู่ที่ความผิดหวังนาน แต่หาว่าครั้งหน้าจะทำให้ดีขึ้นได้ยังไง',tOthr:'เวลาเลือกทางชีวิต เธอคิดถึงคนที่รักก่อนเสมอ ซึ่งเป็นความอ่อนโยน แต่อย่าลืมถามใจตัวเองด้วย',tSelf:'เวลาเลือกทางชีวิต เธอฟังเสียงของตัวเองชัดขึ้นเรื่อย ๆ แม้บางครั้งจะต้องอธิบายให้คนอื่นเข้าใจ'};
function feTraits(){const T=AX.map(a=>({a,...trPos(a)}));if(T.every(x=>x.n<2))return '';const ss=G.strS||[],sf=G.strF||[];const both=ss.filter(x=>sf.includes(x));
 return `<section class="st-card fe-card trx"><div class="fe-h"><h3>ลึกลงไปในตัวฉัน</h3><span class="st-cc md">จาก ${T.reduce((a,x)=>a+x.n,0)} การเลือก</span></div><p class="fe-note">ไม่มีฝั่งไหนดีกว่ากัน จุดบอกว่าเธอเอนไปทางไหนจากสิ่งที่เลือกจริงในเกม</p>
 <div class="trx-l">${T.map(x=>{const p=Math.round(50+x.p*46);return `<div><small>${x.a[4]}</small><span class="trx-b"><em class="${x.p<-.15?'on':''}">${x.a[2]}</em><i><u style="left:${p}%"></u></i><em class="${x.p>.15?'on':''}">${x.a[3]}</em></span></div>`}).join('')}</div>
 ${ss.length?`<div class="trx-s"><div><small>คำที่ฉันเลือกให้ตัวเอง</small><p>${ss.map(w=>`<b class="${both.includes(w)?'m':''}">${w}</b>`).join('')}</p></div><div><small>คำที่เพื่อนเลือกให้</small><p>${sf.map(w=>`<b class="${both.includes(w)?'m':''}">${w}</b>`).join('')}</p></div></div><p class="fe-note">${both.length>=2?'เธอมองตัวเองตรงกับที่เพื่อนเห็นมาก แปลว่าเธอแสดงตัวตนออกมาอย่างที่เป็น':both.length===1?`คำที่ตรงกันคือ "${both[0]}" ส่วนคำอื่นเป็นด้านที่คนอื่นเห็น แต่เธออาจยังไม่ได้มองตัวเองแบบนั้น`:'เพื่อนมองเห็นด้านที่ต่างจากที่เธอมองตัวเอง ลองถามเพื่อนจริง ๆ ดูว่าเห็นอะไรในตัวเธอ'}</p>`:''}</section>`}
/* strengths picker */
const STRW=[['ใจเย็น','tHead'],['ตลก','tOut'],['ขยัน','tPlan'],['ช่างสังเกต','I'],['ใจดี','S'],['กล้า','tBold'],['ละเอียด','C'],['สร้างสรรค์','A'],['เป็นผู้นำ','E'],['ลงมือทำจริง','R'],['รับฟังเก่ง','tHeart'],['ยืดหยุ่น','tFlow'],['ซื่อตรง','tSelf'],['มุ่งมั่น','tIntr'],['อบอุ่น','tOthr'],['มองโลกในแง่ดี','tGrow']];
function strScore(k){if('RIASEC'.includes(k))return (G.ci[k]||0);return ((G.tr||{})[k]||0)*1.4}
function vStr(s){const sel=G.strSel||(G.strSel=[]);return `<section class="st-card"><h2>${s.title}</h2><p class="st-t">ครูปุ้มแจกการ์ดคำศัพท์สิบหกใบ "เลือกสามคำที่เพื่อนสนิทน่าจะใช้อธิบายตัวเรา แล้วเดี๋ยวให้เพื่อนข้าง ๆ เลือกให้อีกรอบนะ"</p><div class="str-g">${STRW.map(([w])=>`<button data-st="strp" data-v="${w}" class="${sel.includes(w)?'on':''}">${w}</button>`).join('')}</div><button class="ls-go" data-st="strok"${sel.length===3?'':' disabled'}>${sel.length===3?'ยืนยันสามคำนี้':`เลือกแล้ว ${sel.length}/3`}</button></section>`}
function strFriend(){const sc=STRW.map(([w,k])=>({w,v:strScore(k)+R_()*1.2}));return sc.sort((a,b)=>b.v-a.v).slice(0,3).map(x=>x.w)}
