function swAdmit(){const prep=G.f.prep||0,st=G.lastAlloc?G.lastAlloc.study:3;const gx=[2.3,2.8,3.3,3.7][G.f.gpx||1];
 const tg=Math.max(20,Math.min(95,Math.round(48+prep*5+st*3+(G.f.examDay||0)*2+(R_()-.5)*18)));const tu=Math.max(15,Math.min(98,Math.round(45+prep*7+st*3.5+(G.f.why==='exp'?3:0)+(G.f.examDay||0)*3+(R_()-.5)*20)));
 const al=Math.max(15,Math.min(95,Math.round(44+prep*5+st*4+(R_()-.5)*18)));
 const comp=G.f.path==='al'?Math.round((tg*.4+al*.6)*100)/100:Math.round((tg*.3+tu*.7)*100)/100;const cutR=67.1+R_()*3,cutL=59+R_()*3;G.swS={tg,tu,al,comp,gx,cutR:Math.round(cutR*100)/100,cutL:Math.round(cutL*100)/100};
 const okR=gx>=2.5&&(G.f.path==='al'||tu>=55)&&comp>=cutR,okL=(G.f.path==='al'||tu>=20)&&comp>=cutL;const pref=G.f.camp||'rs';let got=null;
 if(G.f.path==='port')got=G.f.portOK?(pref==='lp'?'lp':'rs'):null;
 if(!got){const order=pref==='lp'?['lp','rs']:['rs','lp'];for(const c of order){if(c==='rs'&&okR&&pref!=='lp'){got='rs';break}if(c==='lp'&&okL&&pref!=='rs'){got='lp';break}}}
 G.campus=got;return got}
