function swOffers(){const A=G.apply||[];const fl=G.fld||{};const out=[];
 A.forEach(k=>{const j=JOBS[k];if(!j)return;let p=.52+((fl[j.f]||0)*.025)+((G.f.ivJ||0)*.08)+(G.lic?.1:-.25)+(G.f.minor&&MIN[G.f.minor].f===j.f?.08:0);if(j.ex===1)p=G.f.kp?p:0;if(j.ex===2)p=G.f.lkp?p:0;if(k==='pri')p-=.1;if(R_()<Math.max(.1,Math.min(.92,p)))out.push(k)});
 if(!out.length)out.push(A.includes('ngo')?'ngo':A.includes('lab')?'lab':'emp');G.offersSW=out;return out}

