 add({id:'w0.6',per:'S0',fixed:1,title:'ประกาศผล',text:'คะแนนสอบออกแล้ว และระบบประกาศผลการคัดเลือกรอบ 3',q:'ก่อนกดดูผล เธอทำอะไร',opts:[['ดูคนเดียวในห้อง','tIn+1'],['ดูพร้อมครอบครัว','fam+1 rPar+5'],['ให้เพื่อนสนิทดูให้','help+1']],after:G=>{if(G.f.portOK){G.campus=G.f.camp==='lp'?'lp':'rs';return `เธอยืนยันสิทธิ์จากรอบ 1 แล้ว ได้เรียนที่${CAMN[G.campus]}`}const c=swAdmit(),S=G.swS;return (G.f.path==='al'?`TGAT ${S.tg} · A-Level เฉลี่ย ${S.al} · คะแนนรวม ${S.comp}`:`TGAT ${S.tg} · วิชาเฉพาะ ${S.tu} · คะแนนรวม ${S.comp}`)+` (คะแนนต่ำสุดปีนี้ รังสิต ${S.cutR} ลำปาง ${S.cutL})`+'\n'+(c?`เธอติดคณะสังคมสงเคราะห์ศาสตร์ ${CAMN[c]}`:'ปีนี้คะแนนยังไม่ถึง')}});
 add({id:'w0.7',per:'S0',when:G=>!G.campus,title:'ปีที่ต้องเริ่มใหม่',text:'เพื่อน ๆ ประกาศคณะกันเต็มฟีด เธอปิดโทรศัพท์แล้วนั่งมองชีตกองเดิม',q:'เธอตัดสินใจยังไง',opts:[['ซิ่ว อ่านใหม่อีกหนึ่งปี','f:siw tGrow+2 fix+1','ปีนั้นยาวที่สุดในชีวิต แต่เธอไม่เคยลังเลเลยว่าอยากไปที่ไหน'],['เรียนคณะใกล้เคียงไปก่อน แล้วสอบใหม่ปีหน้าโดยไม่บอกใครในคณะเก่า','f:siw tPlan+1 stress+1','เธอเรียนไปด้วยอ่านไปด้วยจนแทบไม่ได้นอน']],after:G=>{G.f.prep=(G.f.prep||0)+1;G.campus=G.f.camp==='lp'||G.f.camp==='both'?'lp':'rs';return `ปีต่อมา คะแนนของเธอขึ้นมาเกือบสิบคะแนน เธอติดคณะสังคมสงเคราะห์ศาสตร์ ${CAMN[G.campus]}`}});
