 add({id:'w1.1',per:'S1',title:'วงกลมวันแรก',text:'กิจกรรมต้อนรับน้องสัปดาห์แรก รุ่นพี่ให้ทุกคนนั่งเป็นวงกลม แล้วส่งไม้ให้พูดทีละคนว่า "ทำไมมาเรียนที่นี่" ข้าง ๆ เธอคือแพรวกับภูมิ',q:'พอไม้มาถึงเธอ เธอพูดว่า',opts:[['เล่าเหตุผลจริง ทั้งที่เสียงสั่น','tHeart+1 rPraew+10 rPhum+5 tBold+1','วงเงียบไปครู่หนึ่ง แล้วแพรวก็จับมือเธอ'],['ตอบสั้น ๆ ว่าอยากช่วยคน แล้วส่งไม้ต่อ','tSafe+1','รุ่นพี่ยิ้ม บอกว่าอีกสี่ปีจะถามใหม่'],['ถามกลับว่าแล้วรุ่นพี่ล่ะ','tOut+1 rFon+10','พี่ฝนตอบยาวจนทุกคนหัวเราะและซึ้งไปพร้อมกัน'],['ขอฟังเพื่อนก่อน','tIn+1','เธอฟังเหตุผลของเพื่อนสามสิบคน ไม่มีใครเหมือนกันเลย']]});
 add({id:'w1.k',per:'S1',title:'รูมเมท',text:G=>`ห้องพักในหอ${camp('ที่ลำปาง','ใกล้รังสิต')}มีเตียงสองเตียง อีกเตียงเป็นของข้าว นักศึกษาวิศวกรรมปี 1 ที่ตื่นตีห้าไปวิ่ง เปิดเพลงตอนอาบน้ำ และพูดเร็วจนเธอตามไม่ทัน คืนแรกข้าวถามว่า "เราตั้งกติกาห้องกันไหม"`,q:'เธอตอบว่า',opts:[['ตั้งเลย เขียนแปะหลังประตู','C+1 rKhao+5 f:khaoMet','กติกาข้อแรกที่ข้าวเขียนคือ "ห้ามเปิดไฟตอนอีกคนนอน" ข้อที่สองที่เธอเขียนคือ "บอกกันตรง ๆ"'],['ไม่ต้องหรอก','tFlow+1 f:khaoMet','สามสัปดาห์แรกผ่านไปด้วยดี จนถึงคืนที่ข้าวพาเพื่อนมาติวในห้อง'],['ถามข้าวก่อนว่ามีอะไรที่ทนไม่ได้บ้าง','kEng+1 rKhao+10 f:khaoMet','ข้าวหัวเราะ "ไม่มีใครเคยถามแบบนี้เลย" แล้วเล่ายาวจนตีหนึ่ง'],['ตกลงทุกข้อที่ข้าวเสนอ ทั้งที่บางข้อไม่ค่อยสะดวกสำหรับตัวเอง','tOthr+1 stress+1 f:khaoMet','ห้องสงบ แต่เธอรู้สึกเหมือนเป็นแขกในห้องตัวเอง']]});
 add({id:'w1.2',per:'S1',title:'คาบปรัชญาและแนวคิด',text:'อาจารย์เขียนบนกระดานว่า "ความยากจนเป็นความรับผิดชอบของใคร" แล้วให้ทุกคนยืนเลือกฝั่ง',q:'เธอยืนฝั่งไหน',opts:[['โครงสร้างสังคม','eJust+2 lvMac+1','อาจารย์ถามต่อว่า "แล้วคนตรงหน้าเราทำอะไรได้บ้างระหว่างรอโครงสร้างเปลี่ยน"'],['ทั้งตัวบุคคลและสังคมร่วมกัน','tHead+1 lvMez+1','อาจารย์บอกว่านี่คือมุมที่งานสังคมสงเคราะห์ใช้ทำงานจริง คนกับสภาพแวดล้อมแยกจากกันไม่ได้'],['ตัวบุคคลต้องพยายามเอง','eSelf+1 tSafe+1','อาจารย์ไม่ได้บอกว่าผิด แต่ให้ไปอ่านงานวิจัยเรื่องกับดักความยากจนมาคุยกัน'],['ยืนตรงกลาง ขอฟังทั้งสองฝั่งก่อนตัดสินใจ','tHead+1 tIn+1','เธอฟังจนจบคาบ และเขียนข้อโต้แย้งของทั้งสองฝั่งได้ครบ']]});
 add({id:'w1.3',per:'S1',title:'ตลาดนัดกิจกรรม',text:'ตลาดนัดกิจกรรมของคณะเปิดรับสมาชิกใหม่ โต๊ะเรียงยาวตลอดลานหน้าตึก',q:'เธอสมัครอะไร',opts:[['ค่ายอาสาพัฒนาชุมชน','fComm+1 kGrp+1 S+1 mCD+1','ค่ายแรกจะออกเดินทางช่วงปิดเทอม'],['สโมสรนักศึกษาคณะ ฝ่ายวิชาการ','lead+1 E+1 kNet+1','เธอได้ดูแลงานติวให้รุ่นน้อง'],['กลุ่มกิจกรรมจิตสังคม','fMent+1 kEng+1','กิจกรรมแรกคือวงคุยเรื่องความเครียดของนักศึกษา'],['ไม่สมัคร','inc+1 doer+1','เธอได้งานร้านกาแฟใกล้หอ สัปดาห์ละสามวัน']]});
 add({id:'w1.f',per:'S1',title:'คนที่ไม่มีใครรู้จัก',text:'ที่มหาวิทยาลัยไม่มีใครรู้จักเธอมาก่อน ไม่มีใครจำได้ว่าตอนมัธยมเธอเป็นคนเงียบ เป็นคนเก่ง หรือเป็นคนที่ชอบหลบหลังห้อง ทุกอย่างเริ่มใหม่ได้',q:'เธออยากลองเป็นคนแบบไหน',opts:[['คนเดิม','tSafe+1 tStuck+0','เธอรู้สึกสบายใจที่ไม่ต้องแสดงเป็นใคร'],['คนที่กล้ายกมือถามในห้องบรรยายสามร้อยคน แม้เสียงจะสั่น','tBold+2 tGrow+1 f:frame1=bold','ครั้งแรกเสียงสั่นจริง ครั้งที่สามไม่สั่นแล้ว'],['ลองลงสมัครตัวแทนชั้นปี','lead+1 tOut+2 f:frame1=lead','เธอได้คะแนนเป็นอันดับสอง แต่ได้รู้จักคนทั้งชั้นปี'],['คนที่ปฏิเสธเป็น','eBound+1 tSelf+1 f:frame1=no','คำว่า "ไม่" ครั้งแรกยากมาก แต่คนที่ฟังไม่ได้โกรธอย่างที่คิด']]});
