 add({id:'w2.o',per:'S2',title:'สามชั่วโมงที่ต้องนั่งดู',text:'วิชาสังคมวิทยาเบื้องต้นให้ไปนั่งสังเกตพื้นที่สาธารณะหนึ่งแห่งสามชั่วโมง ห้ามคุย ห้ามถ่ายหน้าคน แล้วเขียนว่าเห็นโครงสร้างสังคมอะไรบ้าง',q:'เธอเลือกไปที่ไหน',opts:[['ห้องรอตรวจผู้ป่วยนอก โรงพยาบาลรัฐ','fMed+2 mMW+1','เธอเห็นผู้สูงอายุคนหนึ่งรอคิวตั้งแต่ตีห้า และไม่มีใครมาด้วย'],['ใต้สะพานลอยหน้าสถานีขนส่ง','fComm+1 eJust+1 mCD+1','คนขายของ คนไร้บ้าน และเด็กเร่ร่อนใช้พื้นที่เดียวกันโดยมีกติกาที่มองไม่เห็น'],['หน้าโรงงานตอนเปลี่ยนกะ','fLab+2 mLW+1','คนงานหลายร้อยคนเดินสวนกัน เสียงพูดสามภาษาปนกัน'],['สนามเด็กเล่นในสวนสาธารณะ','fChild+2 mCF+1','เด็กที่มากับพี่เลี้ยงกับเด็กที่มาคนเดียวเล่นแยกกันโดยไม่มีใครสั่ง'],['ศาลาวัดวันพระ','fElder+2 mWO+1','ผู้สูงอายุนั่งคุยกันเป็นกลุ่ม บางคนมาแค่เพื่อจะได้มีคนคุยด้วย']]});
 add({id:'w1.5',per:'S2',title:'จิตอาสาวันหยุด',text:'คณะเปิดให้นักศึกษาปี 1 เลือกจิตอาสาวันหยุดหนึ่งที่ตลอดเทอม',q:'เธอเลือกที่ไหน',opts:[['สถานสงเคราะห์คนชรา','fElder+2 tHeart+1 mWO+1'],['สถานรองรับเด็ก','fChild+2 S+1 mCF+1'],['ศูนย์ฝึกอาชีพคนพิการ','fDis+2 R+1'],['หน่วยแจกอาหารคนไร้บ้าน','fComm+1 fPol+1 eJust+1 mCD+1']]});
 add({id:'w2.p',per:'S2',title:'ตรงกลางระหว่างเพื่อนสองคน',text:'งานกลุ่มวิชาเศรษฐศาสตร์เบื้องต้น แพรวกับภูมิทะเลาะกันกลางห้องสมุด แพรวหาว่าภูมิไม่ช่วย ภูมิบอกว่าแพรวไม่เคยถามความเห็นใคร ทั้งคู่หันมามองเธอพร้อมกัน',q:'เธอทำยังไง',opts:[['ไม่เลือกข้าง ขอให้ทุกคนพักสิบนาทีก่อน','kGrp+1 eBound+1 rPraew+3 rPhum+3','พอกลับมาคุยกัน เสียงเบาลงครึ่งหนึ่ง'],['เข้าข้างแพรว เพราะสนิทกว่า','rPraew+8 rPhum-10','แพรวขอบคุณ แต่ภูมินั่งเงียบไปจนจบงาน'],['ขอให้แต่ละคนบอกว่าต้องการอะไรจากอีกฝ่าย','kEng+1 kGrp+2 tBold+1','ภูมิบอกว่าอยากให้ถามก่อน แพรวบอกว่าอยากให้ตอบแชท ทั้งคู่หัวเราะออกมาพร้อมกัน'],['รับทำส่วนที่เหลือเองหมด','tOthr+1 stress+2','งานเสร็จ ทุกคนเลิกทะเลาะ แต่เธอนอนตีสามสามคืนติด']]});
