 add({id:'w3.v',per:'S3',kind:'multi',n:3,title:'วิชาดูงานและสัมมนา',text:'วิชาดูงานพาไปเห็นหน่วยงานจริงครั้งแรก นักศึกษาเลือกได้สามแห่งจากหกแห่ง แต่ละแห่งตรงกับวิชาโทหนึ่งสายของคณะ',q:'เลือกที่ดูงาน 3 แห่ง',opts:[['ฝ่ายสังคมสงเคราะห์ โรงพยาบาล','f:vis_MW'],['สถานพินิจและคุ้มครองเด็กและเยาวชน','f:vis_JA'],['บ้านพักเด็กและครอบครัว','f:vis_CF'],['ศูนย์พัฒนาการจัดสวัสดิการสังคมผู้สูงอายุ','f:vis_WO'],['สำนักงานประกันสังคมและโรงงานในนิคมอุตสาหกรรม','f:vis_LW'],['ชุมชนบ้านมั่นคงริมคลอง','f:vis_CD']]});
 const VIS={MW:['ห้องฉุกเฉินตอนสิบโมงเช้า นักสังคมสงเคราะห์ของโรงพยาบาลคุยโทรศัพท์สองสายพร้อมกัน สายหนึ่งตามญาติผู้ป่วยไม่ทราบชื่อ อีกสายประสานสิทธิการรักษาให้ผู้ป่วยแรงงานข้ามชาติ ระหว่างวางสายเธอหันมาบอกนักศึกษาว่า "ที่นี่ไม่มีเคสไหนรอได้"'],JA:['ประตูเหล็กสามชั้นกว่าจะถึงห้องประชุม เด็กชายอายุสิบหกคนหนึ่งออกมาเล่าเรื่องตัวเองให้นักศึกษาฟัง เขาพูดประโยคหนึ่งที่ทั้งห้องเงียบ "ผมไม่เคยมีผู้ใหญ่คนไหนฟังผมจนจบ จนมาอยู่ที่นี่"'],CF:['ห้องกิจกรรมของบ้านพักเด็กมีรูปวาดติดเต็มผนัง เด็กหญิงตัวเล็กคนหนึ่งเดินมาจับมือเธอแล้วไม่ยอมปล่อยจนกลับ พี่เลี้ยงกระซิบว่า "เด็กที่เพิ่งเข้ามาใหม่มักจับมือทุกคน เพราะยังไม่รู้ว่าใครจะอยู่"'],WO:['ผู้สูงอายุกลุ่มหนึ่งกำลังรำวงในห้องกิจกรรม ผู้สูงอายุหญิงคนหนึ่งดึงเธอเข้าวง แล้วเล่าว่าอยู่ที่ศูนย์มาแปดปี ลูกมาเยี่ยมปีละครั้งตอนสงกรานต์ "แต่ที่นี่มีเพื่อน ไม่เหงาเท่าอยู่บ้านคนเดียว"'],LW:['เจ้าหน้าที่ประกันสังคมอธิบายสิทธิตามมาตรา 33 39 และ 40 เร็วจนจดไม่ทัน แล้วพาไปดูโรงงานในนิคม ฝ่ายสวัสดิการเล่าว่าเดือนก่อนมีคนงานนิ้วขาดจากเครื่องจักร และต้องดูแลทั้งค่ารักษา เงินทดแทน และครอบครัวที่ไม่มีรายได้'],CD:['ชุมชนริมคลองที่เคยถูกไล่รื้อ ตอนนี้มีบ้านแถวสีเหลืองเรียงกันเป็นระเบียบ ประธานชุมชนเล่าว่าใช้เวลาเจ็ดปีกว่าจะรวมกลุ่มออมทรัพย์ เจรจาเรื่องที่ดิน และสร้างบ้านเอง "นักศึกษาจำไว้นะ ไม่มีใครมาสร้างให้ เราสร้างกันเอง"']};
 MNK.forEach(k=>add({id:'w3.v'+k,per:'S3',when:G=>!!G.f['vis_'+k],title:'ดูงาน · '+MIN[k].s,text:VIS[k][0],q:'ระหว่างทางกลับ ใจเธอเป็นยังไง',opts:[['อยากกลับไปที่นั่นอีก','m'+k+'+3 '+MIN[k].f+'+2','เธอเขียนชื่อหน่วยงานนี้ไว้ในสมุดพร้อมดาวหนึ่งดวง'],['สนใจ แต่ยังนึกภาพตัวเองทำงานแบบนั้นทุกวันไม่ออก','m'+k+'+1','เธอเก็บคำถามนี้ไว้ถามรุ่นพี่'],['หนักใจ','m'+k+'-1 stress+1','คืนนั้นภาพที่เห็นยังวนอยู่ในหัว'],['รู้สึกว่าไม่ใช่ทางของเรา และนั่นก็เป็นคำตอบที่ดี','m'+k+'-2 tHead+1','การรู้ว่าอะไรไม่ใช่ ทำให้ทางที่ใช่แคบลงและชัดขึ้น']]}));
 add({id:'w3.r',per:'S3',title:'ฝึกสัมภาษณ์ในห้องเรียน',text:'วิชาหลักและวิธีการสังคมสงเคราะห์ 1 อาจารย์ให้จับคู่เล่นบทบาทสมมติ เธอได้เป็นนักสังคมสงเคราะห์ คู่ของเธอเล่นเป็นผู้รับบริการที่ไม่ยอมพูด',q:'เธอทำยังไงเมื่อคู่ของเธอเงียบนาน',opts:[['นั่งเงียบด้วย ให้เวลา แล้วสะท้อนความรู้สึกที่เห็น','kEng+2 tHeart+1','คู่ของเธอหลุดหัวเราะ บอกว่า "เฮ้ย ได้ผลจริงด้วย"'],['เปลี่ยนเป็นคำถามปลายปิด','kAss+1 tHead+1','ได้ข้อมูลมาทีละนิด อาจารย์บอกว่าใช้ได้ แต่ระวังจะกลายเป็นการสอบสวน'],['เล่าเรื่องของตัวเองก่อนเพื่อให้เขาเปิดใจ','eBound-1 tOut+1','อาจารย์ชวนคิดว่าการเปิดเผยตัวเองมากไป อาจทำให้ศูนย์กลางย้ายมาอยู่ที่เรา'],['หยุดแล้วถามอาจารย์','help+1 tGrow+1','อาจารย์ให้ทั้งห้องดูเธอเป็นตัวอย่าง แล้วสอนเทคนิคการอยู่กับความเงียบ']]});
 add({id:'w3.e',per:'S3',title:'คาบจริยธรรมทางวิชาชีพ',text:'อาจารย์ฉายกรณีศึกษา เด็กอายุสิบห้าเล่าให้นักสังคมสงเคราะห์ฟังว่ากำลังตั้งครรภ์ และขอร้องไม่ให้บอกผู้ปกครองเพราะกลัวถูกไล่ออกจากบ้าน ทั้งห้องแบ่งเป็นสองฝั่งทันที',q:'เธอคิดว่านักสังคมสงเคราะห์ควรเริ่มจากอะไร',opts:[['ประเมินความปลอดภัยของเด็กก่อน','eSafe+2 kAss+1','อาจารย์ถามต่อว่าถ้าบ้านไม่ปลอดภัยจริง กฎหมายคุ้มครองเด็กให้ทางเลือกอะไรบ้าง'],['เคารพความต้องการของเด็ก','eSelf+2 eConf+1','อาจารย์ถามว่า "อายุสิบห้า ตัดสินใจเองได้แค่ไหนในทางกฎหมาย"'],['บอกเด็กตั้งแต่แรกว่าเรื่องไหนเก็บเป็นความลับได้ เรื่องไหนต้องแจ้งเพื่อความปลอดภัยของเขาเอง','eConf+2 kEng+1','อาจารย์บอกว่าการบอกขอบเขตตั้งแต่ต้นทำให้ความไว้ใจไม่พังทีหลัง'],['แจ้งผู้ปกครองตามหน้าที่','eSafe+1 tSafe+1','เพื่อนฝั่งตรงข้ามถามว่า "แล้วถ้าเด็กหนีออกจากบ้านคืนนั้นล่ะ"']]});
 add({id:'w3.g',per:'S3',title:'คนที่ไม่ตอบแชท',text:'งานกลุ่มวิชาพฤติกรรมมนุษย์ เธอได้อยู่กลุ่มเดียวกับมุก เพื่อนที่ไม่ค่อยมีใครรู้จัก มุกไม่ตอบแชทกลุ่มมาสี่วัน อีกสามวันต้องส่งงาน เพื่อนในกลุ่มเริ่มพิมพ์ว่า "ตัดชื่อออกเลยไหม"',q:'เธอทำยังไง',opts:[['ทักมุกส่วนตัว','rMook+10 kEng+1 f:mookMet','มุกตอบตอนตีหนึ่ง "ขอโทษนะ ช่วงนี้ไม่ค่อยมีเวลา ส่งส่วนของเราพรุ่งนี้เช้า" และส่งมาจริง'],['เห็นด้วยกับเพื่อนว่าตัดชื่อ','rMook-15 f:mookMet','มุกรู้ตอนอาจารย์ประกาศคะแนน แล้วไม่มองหน้าใครในกลุ่มอีกเลย'],['แบ่งงานใหม่ และบอกอาจารย์ตามจริง','kGrp+1 eJust+1 f:mookMet rMook+3','อาจารย์ขอบคุณที่ซื่อตรง และเรียกมุกไปคุยแยก'],['ทำส่วนของมุกเองเงียบ ๆ','tOthr+1 stress+1 f:mookMet','ไม่มีใครรู้ แม้แต่มุก']]});
 /* ===== ปี 2 เทอม 2 · วิชาโท ===== */
 add({id:'w4.r',per:'S4',title:'หัวข้องานวิจัยรายวิชา',text:'วิชาการวิจัยทางสังคมสงเคราะห์ต้องทำวิจัยเล็ก ๆ หนึ่งชิ้นตลอดเทอม เก็บข้อมูลจริงกับคนจริง',q:'เธอเลือกหัวข้อแบบไหน',opts:[['การเข้าถึงสิทธิของผู้สูงอายุที่อยู่ลำพัง','fElder+2 kRes+2 mWO+1'],['ความเครียดของเด็กในครอบครัวแหว่งกลาง','fChild+2 kRes+2 mCF+1'],['ภาระค่าใช้จ่ายของผู้ป่วยแรงงานนอกระบบ','fMed+2 kRes+1 eJust+1 mMW+1'],['ชีวิตของไรเดอร์ส่งอาหารที่ไม่มีประกันสังคมแบบลูกจ้าง','fLab+2 kRes+2 mLW+1'],['การกลับคืนสู่ชุมชนของเยาวชนที่พ้นจากสถานพินิจ','fJust+2 kRes+1 mJA+1'],['ทำไมกลุ่มออมทรัพย์บางชุมชนอยู่ได้ยี่สิบปี บางชุมชนล้มในสองปี','fComm+2 kRes+2 mCD+1']]});
 add({id:'w4.h',per:'S4',title:'ช่วงเวลาที่เวลาผ่านไปเร็ว',text:'ก่อนเลือกวิชาโท อาจารย์ที่ปรึกษาให้เขียนตอบคำถามเดียว "ตลอดสองปีที่ผ่านมา ตอนไหนที่เธอลืมดูนาฬิกา"',q:'คำตอบของเธอใกล้กับข้อไหนที่สุด',opts:[['ตอนนั่งฟังผู้ป่วยในโรงพยาบาลเล่าเรื่องชีวิต','mMW+3'],['ตอนที่เด็กคนหนึ่งเริ่มยิ้มให้','mCF+3'],['ตอนนั่งคุยกับผู้สูงอายุจนเย็น','mWO+3'],['ตอนถกกันเรื่องความยุติธรรมและโอกาสครั้งที่สอง','mJA+3'],['ตอนเห็นชาวบ้านรวมตัวกันตัดสินใจเรื่องของตัวเอง','mCD+3'],['ตอนอ่านเรื่องสิทธิแรงงานแล้วนึกถึงพ่อแม่ตัวเอง','mLW+3']]});
 add({id:'w4.f',per:'S4',title:'เสียงรอบตัว',text:G=>`แพรวประกาศในกลุ่มว่าจะเลือกสายสุขภาพและการแพทย์ "ไปด้วยกันไหม" ${G.f.phumLeft?'ภูมิส่งข้อความมาจากคณะใหม่ว่า "เลือกตามใจนะ อย่าเลือกตามเรา"':'ภูมิบอกว่าจะเลือกพัฒนาชุมชน "อย่างน้อยได้ออกไปข้างนอก"'} ส่วนที่บ้าน แม่ส่งลิงก์ข่าวเปิดสอบราชการกระทรวงยุติธรรมมาให้สามลิงก์`,q:'เสียงไหนดังที่สุดในหัวเธอ',opts:[['เสียงตัวเอง','tSelf+2 tBold+1','เธอปิดแชททุกห้อง แล้วนั่งอ่านคำอธิบายรายวิชาทั้งหกสายใหม่ตั้งแต่ต้น'],['แพรว','rPraew+5 tOthr+1 mMW+1','การได้เรียนกับเพื่อนสนิทก็เป็นเหตุผลที่ดีข้อหนึ่ง'],['แม่','rPar+5 tOthr+1 mJA+1','เธอคิดถึงคำว่ามั่นคงที่แม่พูดมาตลอดชีวิต'],['รุ่นพี่','help+1 rFon+5','พี่ฝนบอกว่า "เลือกสายที่เธอยอมเหนื่อยให้ได้ ไม่ใช่สายที่เหนื่อยน้อยที่สุด"']]});
 add({id:'w4.m',per:'S4',title:'เลือกวิชาโท',text:G=>{const t=MNK.map(k=>({k,v:(G.mn||{})['m'+k]||0})).sort((a,b)=>b.v-a.v);return `คณะมีวิชาโทหกสาย เรียนสิบห้าหน่วยกิตตลอดปี 3 และปี 4 จากทุกการเลือกที่ผ่านมา ใจเธอตอบสนองกับสาย${MIN[t[0].k].s}มากที่สุด รองลงมาคือ${MIN[t[1].k].s} แต่การเลือกครั้งนี้เป็นของเธอ`},q:'เธอเลือกวิชาโทสายไหน',opts:MNK.map(k=>[`${MIN[k].n}`,`f:minor=${k} m${k}+2 ${MIN[k].f}+2`,MIN[k].d])});
 add({id:'w4.s',per:'S4',title:'ปฐมนิเทศก่อนฝึกภาคปฏิบัติ',text:'ห้องประชุมใหญ่ อาจารย์ฝ่ายการศึกษาภาคปฏิบัติอธิบายกติกา ห้ามเยี่ยมบ้านคนเดียว ห้ามนำเอกสารของหน่วยงานออกนอกพื้นที่ ห้ามโพสต์อะไรที่ระบุตัวผู้รับบริการได้ แจ้งเพื่อนร่วมงานทุกครั้งที่ออกนอกสถานที่',q:'เรื่องไหนที่เธอกังวลที่สุด',opts:[['กลัวทำอะไรผิดแล้วกระทบผู้รับบริการ','tHeart+1 eSafe+1','อาจารย์บอกว่าความกลัวนี้คือสิ่งที่ทำให้เราระวัง'],['กลัวพี่เลี้ยงดุ','tSafe+1 stress+1','รุ่นพี่ข้าง ๆ กระซิบว่า "ส่วนใหญ่ดุเพราะห่วงนะ"'],['กลัวเห็นเรื่องที่หนักเกินรับไหว','fMent+1 help+1','อาจารย์บอกว่ามีการนิเทศงานทุกสัปดาห์ เพื่อให้มีที่วางเรื่องหนัก'],['ไม่ค่อยกังวล','tBold+1 conf+1','เธออยากรู้มากกว่าว่าจะได้เจอใคร']]});
