 add({id:'w6.c',per:'S6',title:'ห้องกระจกด้านเดียว',text:'วิชาการให้การปรึกษาทางสังคมสงเคราะห์ ทุกคนต้องให้การปรึกษาผู้รับบริการจำลองยี่สิบนาที อาจารย์และเพื่อนดูอยู่หลังกระจกด้านเดียว แล้วเปิดวิดีโอให้ดูตัวเองทีหลัง',q:'ตอนดูวิดีโอตัวเอง เธอเห็นอะไร',opts:[['ตัวเองพูดมากกว่าฟัง','tGrow+2 kEng+1','สัปดาห์ต่อมาเธอนับในใจถึงสามก่อนพูดทุกครั้ง'],['ตัวเองรีบให้คำแนะนำ','kPlan+1 tGrow+1','อาจารย์บอกว่า "คำแนะนำที่ดีที่สุด คือคำที่ผู้รับบริการพูดออกมาเอง"'],['ตัวเองนิ่งกว่าที่คิด','conf+1 kEng+2','เพื่อนบอกว่าดูแล้วอยากเล่าเรื่องให้ฟังจริง ๆ'],['ไม่กล้าดูจนจบ','stress+1 tStuck+1','อาจารย์นั่งดูด้วยจนจบ แล้วชี้ให้เห็นสองนาทีที่เธอทำได้ดีมาก']]});
 add({id:'w6.x',per:'S6',title:'คำว่าใช่ที่ไม่ได้มาจากใจ',text:'เธอสังเกตว่าตัวเองตอบรับทุกอย่าง งานกลุ่ม งานสโมสร งานติวน้อง ช่วยเพื่อนย้ายหอ ปฏิทินเต็มจนไม่มีวันว่าง คืนนี้รุ่นพี่ทักมาขอให้ช่วยงานอีกหนึ่งงาน',q:'เธอตอบว่า',opts:[['ปฏิเสธ','eBound+2 tSelf+2 tGrow+1 f:frame2=no','ส่งไปแล้วใจเต้นแรง แต่รุ่นพี่ตอบว่า "ได้เลย ขอบคุณที่บอกตรง ๆ"'],['รับ แล้วนอนดึกเหมือนเดิม','tOthr+1 stress+2','งานเสร็จ ทุกคนพอใจ ยกเว้นร่างกายของเธอ'],['ขอเวลาคิดหนึ่งคืน แล้วลองเขียนดูว่าทำไมถึงปฏิเสธใครไม่ได้','tIntr+1 tGrow+2 f:frame2=think','เธอเขียนได้หนึ่งหน้า บรรทัดสุดท้ายคือ "กลัวว่าถ้าไม่ช่วย จะไม่มีใครอยากอยู่ด้วย"'],['รับ แต่ลดงานอื่นที่ไม่จำเป็นออกหนึ่งอย่าง','tPlan+1 eBound+1','เธอเพิ่งรู้ว่าการเลือกก็คือการตัดบางอย่างออก']]});
