function swBuild(){const S=[].concat(swMain(),swMinorScenes(),swLic(),swJobs(),swWork());const by={};S.forEach(s=>(by[s.per]=by[s.per]||[]).push(s));
 const SL={S1:2,S2:2,S3:2,S4:2,S5:1,S6:2,S7:2,S8:1,S9:2,S10:1,S13:2};const blocks={S5:swPrac1(),S8:swPrac2(),S10:swPrac3()};
 const late=['w10.g','n.fit','n.doubt','w9.f','w4.s'];const Q=[];
 PERS_SW.forEach(p=>{if(SWIL[p])Q.push({id:'i-'+p,kind:'story',per:p,pool:SWIL[p]});
  if(SW_TIME.includes(p))Q.push({id:'t-'+p,kind:'time',per:p});
  if(SWIL2[p])Q.push({id:'k-'+p,kind:'story',per:p,pool:SWIL2[p]});
  const arr=by[p]||[];arr.filter(s=>!late.includes(s.id)&&s.id!=='w7.5').forEach(s=>Q.push(s));
  if(blocks[p])blocks[p].forEach(s=>Q.push(s));
  if(SL[p])Q.push({id:'s-'+p,kind:'slot',per:p,n:SL[p]});
  arr.filter(s=>late.includes(s.id)).forEach(s=>Q.push(s));
  if(UNIT.includes(p))Q.push({id:'g-'+p,kind:'grade',per:p});
  arr.filter(s=>s.id==='w7.5').forEach(s=>Q.push(s))});
 return Q}
