function swRel(){const msg=(k,hi,md,lo)=>relv(k)>=60?hi:relv(k)>=35?md:lo;const R=[['แพรว','rPraew',msg('rPraew','"สี่ปีที่ผ่านมา ถ้าไม่มีแก เราคงไม่รอดมาถึงวันรับปริญญา"','"เราอาจไม่ได้คุยกันทุกวันแล้ว แต่เรายังจำคืนติวสอบได้"','"ขอโทษที่ช่วงหลังเราห่างกันไปนะ"')],['ภูมิ','rPhum',msg('rPhum','"ขอบใจที่วันนั้นถามว่าเราอยากเป็นใคร"','"ยังจำบทบาทสมมติวันนั้นได้ไหม เราเงียบนานมากเลย"','"เราคงไม่ได้เล่าให้ฟังว่าคิดอะไรอยู่ตอนนั้น"')],['พี่ฝน','rFon',msg('rFon','"ยินดีต้อนรับสู่อาชีพนี้นะน้อง ดูแลตัวเองด้วย"','"มีอะไรทักพี่มาได้เสมอ"','"ขอให้น้องเจอที่ที่ใช่นะ"')]];if(G.f.mookMet)R.push(['มุก','rMook',msg('rMook','"ขอบใจที่วันนั้นซื้อนมให้ เราไม่เคยลืมเลย"','"ขอบใจที่ไม่ตัดชื่อเราออกนะ"','"เราคงเป็นเพื่อนที่เข้าใจยากไปหน่อย"')]);if(G.f.khaoMet)R.push(['ข้าว','rKhao',msg('rKhao','"รูมเมทที่ดีที่สุดในชีวิตเลย"','"กติกาหลังประตูยังอยู่นะ"','"ขอโทษเรื่องคืนนั้นนะ"')]);if(G.f.tukMet)R.push(['พี่ตุ๊ก','rTuk',msg('rTuk','"พี่ดีใจที่ได้เห็นน้องเติบโตจากบันทึกเล่มแรก"','"จำไว้นะ ซื่อสัตย์กับสิ่งที่ไม่รู้"','"ขอให้น้องเจอพี่เลี้ยงที่ดีกว่าพี่นะ"')]);if(G.f.ajMet)R.push(['อาจารย์วรรณ','rAj',msg('rAj','"ครูภูมิใจในตัวเธอ"','"ประตูห้องครูเปิดไว้เสมอ"','"ขอให้เธอเจอทางของตัวเอง"')]);R.push(['ที่บ้าน','rPar',msg('rPar','"ภูมิใจในตัวลูกที่สุด"','"เหนื่อยก็กลับบ้านมาพักนะ"','"อาจไม่เข้าใจงานลูกทั้งหมด แต่เป็นห่วงเสมอ"')]);
 return `<section class="st-card"><h3>ข้อความจากคนสำคัญ</h3>${R.map(([n,k,t])=>`<div class="st-msg"><div><b>${n}</b><i><u style="width:${relv(k)}%"></u></i></div><p>${esc(t)}</p></div>`).join('')}</section>`}
function swMoments(){const A=(G.log||[]).filter(e=>e&&e.id&&/^s-/.test(e.id));if(!A.length)return '';return `<section class="st-card"><h3>ช่วงเวลาที่หล่อหลอมฉัน</h3><p class="st-t">เรื่องที่ไม่ได้เลือกให้เกิด แต่เลือกได้ว่าจะรับมือยังไง</p>${A.slice(0,8).map(e=>`<div class="st-mo"><small>${PER[e.p]||''}</small><b>${esc(e.t)}</b><span>${esc(e.c)}</span></div>`).join('')}</section>`}
function swPlan(){const tf=swTop('fld',FLD)[0];const low=Object.keys(SKL).map(k=>({k,v:(G.sk||{})[k]||0})).sort((a,b)=>a.v-b.v)[0];const co=top2(G.cope)[0];
 const Q=[`ถ้าได้ทำงานด้าน${FLD[tf.k][0]}ทุกวัน เธอจะเหนื่อยกับอะไรมากที่สุด และอะไรจะทำให้ยังอยู่ต่อได้`,`ทักษะ${SKL[low.k]}ที่เธอใช้น้อยที่สุด ถ้าต้องใช้ในงานจริงพรุ่งนี้ เธอจะเริ่มฝึกจากตรงไหน`,`ใครคือคนที่เธอจะคุยด้วยในวันที่เคสหนักจนกลับบ้านไปไม่หยุดคิด`];
 return `<section class="st-card fe-plan"><small class="fe-k">ใช้ได้จริงระหว่างเรียน</small><h3>แผน 3 ก้าวถัดไป</h3><p class="fe-note">สาขาที่เข้ากับเธอที่สุดคือ <b>${FLD[tf.k][0]}</b> หน่วยงานที่ทำงานด้านนี้ เช่น ${FLD[tf.k][1]}</p>
 <div class="fe-st"><i>1</i><div><small>ก่อนเลือกวิชาโทและที่ฝึกภาคปฏิบัติ</small><b>ลองสาย${MIN[MNT[swTop('mn',MNT)[0].k]].s}ของจริง</b><span>ถ้ายังเรียนอยู่ ขอไปดูงานหรือเป็นอาสาที่ ${MIN[MNT[swTop('mn',MNT)[0].k]].w} สักหนึ่งวัน แล้วสังเกตว่าเวลาผ่านไปเร็วไหม</span></div></div>
 <div class="fe-st"><i>2</i><div><small>ตลอดปีการศึกษา</small><b>เติมทักษะ${SKL[low.k]}</b><span>ขอโอกาสใช้ทักษะนี้ในการฝึกงานหรือกิจกรรมคณะ แล้วเขียนบันทึกสะท้อนตัวเองทุกครั้ง บันทึกพวกนี้ใช้เขียนบทความสอบสัมภาษณ์ใบอนุญาตได้ด้วย</span></div></div>
 <div class="fe-st"><i>3</i><div><small>ตลอดทาง</small><b>ดูแลตัวเองแบบมืออาชีพ</b><span>${co==='alone'?'หาพี่เลี้ยง อาจารย์ หรือเพื่อนในวิชาชีพไว้หนึ่งคน สำหรับคุยเรื่องเคสหนักโดยรักษาความลับของผู้รับบริการ':(G.st.stress||0)>=6?'ความเครียดของเธอสูงตลอดเกม กันเวลาพักให้ชัดและขอการนิเทศงานเมื่อรู้สึกว่าแบกไม่ไหว':'รักษาสมดุลที่เธอทำได้ในเกมไว้ และอย่าลืมว่าการขอการนิเทศงานคือเรื่องปกติของมืออาชีพ'}</span></div></div>
 <p class="fe-fine">ข้อมูลรอบการสอบ คะแนน และเกณฑ์ใบอนุญาตในเกมอ้างอิงประกาศล่าสุดเท่าที่มี ตรวจประกาศจริงของคณะและสภาวิชาชีพสังคมสงเคราะห์อีกครั้ง</p></section>
 <section class="st-card fe-card"><h3>คำถามไว้คุยต่อ</h3><p class="fe-note">ใช้คุยกับอาจารย์ที่ปรึกษา พี่เลี้ยงฝึกงาน หรือเขียนตอบเองก็ได้</p><ol class="fe-q">${Q.map(q=>`<li>${esc(q)}</li>`).join('')}</ol></section>`}
function vEndSW(){const c2=[swRel(),moodGraph(),voiceSec()].join('');
 return `<div class="lsx st-wrap st-end fe"><div class="stg-hd"><button class="lf-back" data-st="exit">‹ ออกจากเกม</button></div>
 ${swHero()}${swStory()}${swSum()}${feNav()}
 ${feChap('fe-c1','01','นักสังคมสงเคราะห์แบบฉัน','สาขา ระดับงาน ทักษะ และจุดยืนที่เธอเลือกซ้ำ ๆ')}${swProfile()}${swMinor()}${feTraits()}
 ${feChap('fe-c2','02','ใจและคนรอบตัว','ความรู้สึก ความสัมพันธ์ และเสียงในหัวตลอดสี่ปี')}${c2}
 ${feChap('fe-c3','03','เส้นทางที่เดินมา','การฝึกภาคปฏิบัติ เวลาที่ใช้ และการตัดสินใจทั้งหมด')}${swPract()}${timeSec()}${swMoments()}${quickSec()}${fePath()}
 ${feChap('fe-c4','04','ก้าวต่อไป','สิ่งที่ทำได้เลยระหว่างเรียนและหลังจบ')}${swPlan()}
 <section class="st-card fe-card"><h3>ถ้าย้อนกลับไปเลือกใหม่</h3><p class="fe-note">ลองเลือกอีกทางที่ทางแยกสำคัญ เหตุการณ์ระหว่างทางจะสุ่มใหม่ด้วย</p><div class="st-op">${Object.keys(CPS_SW).filter(k=>G.cp&&G.cp[k]).map((k,j)=>`<button data-st="rewind" data-v="${k}"><i>${j+1}</i><b>${CPS_SW[k]}</b></button>`).join('')}</div></section>
 <div class="fe-act"><button class="ls-sk" data-st="share">บันทึกแฟ้มเป็นรูป</button><button class="ls-go" data-st="again">เล่นใหม่อีกรอบ</button></div><div id="ls-img"></div>
 <p class="ls-cr">แฟ้มนี้เป็นข้อสะท้อนตัวเองจากการเล่น ไม่ใช่ผลทดสอบทางจิตวิทยา ข้อมูลทั้งหมดเก็บไว้ในเครื่องของเธอเท่านั้น</p></div>`}

