 if(st.k==='new'){d=sw?'สอบเข้าคณะ ฝึกงานสามครั้ง สอบใบอนุญาต จนถึงงานแรก แล้วดูว่าเธอเป็นนักสังคมสงเคราะห์แบบไหน':'ใช้ชีวิตอีกครั้งตั้งแต่ ม.4 จนถึงงานแรก แล้วดูว่าทุกการเลือกบอกว่าเธอเป็นคนแบบไหน';cta='เริ่มเส้นทาง';k='new'}
