function pgxCard(where){const L=pgxLast();const st=pgxStat();const due=pgxDue();
 return `<section class="pgx ${where}"><div class="pgx-h"><span class="pgx-ic"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v11m0 0l-4-4m4 4l4-4"/><path d="M4 15v3a2 2 0 002 2h12a2 2 0 002-2v-3"/></svg></span><div><b>บันทึกความคืบหน้า</b><small>${L?`บันทึกล่าสุด ${pgxAgo(L.at)} · ${pgxDT(L.at)}`:'ยังไม่เคยบันทึกเป็นไฟล์'}</small></div>${due?'<em>ควรเซฟ</em>':''}</div>
 <p>ความคืบหน้าเก็บอยู่ในเบราว์เซอร์เครื่องนี้เท่านั้น ถ้าล้างข้อมูลเว็บ เปลี่ยนเครื่อง หรือไม่ได้เปิดนาน ข้อมูลอาจหาย เซฟเป็นไฟล์ไว้ แล้วกู้กลับได้ทุกเมื่อ</p>
 <div class="pgx-st"><span><b>${st.q}</b><small>ข้อที่ทำ</small></span><span><b>${st.l}</b><small>บทเรียน</small></span><span><b>${st.c}</b><small>การ์ด</small></span><span><b>${st.k}</b><small>เคส</small></span></div>
 <div class="pgx-btns"><button class="pgx-b1" data-pgx="save">บันทึกความคืบหน้าเป็นไฟล์</button><label class="pgx-b2">กู้ข้อมูลจากไฟล์<input type="file" accept="application/json,.json" data-pgxin></label></div>
 ${typeof navigator!=='undefined'&&navigator.canShare?'<button class="pgx-sh" data-pgx="share">ส่งไฟล์เข้า LINE Keep หรือ Google Drive ›</button>':''}
 <small class="pgx-tip">ทริก ส่งไฟล์เก็บไว้ใน LINE Keep หรือ Drive ของตัวเองด้วย เผื่อมือถือหาย</small></section>`}
function pgxDue(){const st=pgxStat();if(st.q+st.l+st.c+st.k<5)return false;const L=pgxLast();if(!L)return true;return Date.now()-L.at>7*864e5||st.q-(L.q||0)>=30}
function pgxSnooze(){try{return +localStorage.getItem(pgxKey()+':sn')>Date.now()}catch(e){return false}}
function pgxBar(){const L=pgxLast(),st=pgxStat();const d=L?st.q-(L.q||0):st.q;const why=!L?'ยังไม่เคยเซฟความคืบหน้าเป็นไฟล์':Date.now()-L.at>7*864e5?`ไม่ได้เซฟมา ${pgxAgo(L.at)}`:`ทำเพิ่มไปแล้ว ${d} ข้อตั้งแต่เซฟล่าสุด`;
 return `<section class="pgx-bar"><span class="pgx-ic sm"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v11m0 0l-4-4m4 4l4-4"/><path d="M4 15v3a2 2 0 002 2h12a2 2 0 002-2v-3"/></svg></span><div><b>${why}</b><small>เซฟไว้กันข้อมูลหาย ใช้เวลาไม่ถึง 5 วินาที</small></div><button class="pgx-b1" data-pgx="save">เซฟ</button><button class="pgx-x" data-pgx="snooze" aria-label="ไว้ทีหลัง">ไว้ทีหลัง</button></section>`}
function pgxRefresh(){document.querySelectorAll('.pgx,.pgx-bar').forEach(x=>x.remove());pgxPlace()}
function pgxPlace(){const m=document.getElementById('main');if(!m||typeof S==='undefined')return;
 if(V.view==='home'){if(m.querySelector('.pgx-bar')||!pgxDue()||pgxSnooze())return;const host=m.querySelector('.home');if(!host)return;const hello=host.querySelector('.hello');const at=host.querySelector('.lfh')||hello;if(at)at.insertAdjacentHTML('afterend',pgxBar());else host.insertAdjacentHTML('afterbegin',pgxBar());return}
 if(V.view==='more'){if(m.querySelector('.pgx'))return;const g=m.querySelector('#hg-track>.hg-hd');if(g)g.insertAdjacentHTML('afterend',pgxCard('in-more'));return}
 if(V.view==='profile'){if(m.querySelector('.pgx'))return;const lo=m.querySelector('.btn.logout');if(lo)lo.insertAdjacentHTML('beforebegin',pgxCard('in-prof'));else{const h=m.querySelector('.home');if(h)h.insertAdjacentHTML('beforeend',pgxCard('in-prof'))}}}
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('[data-pgx]');if(!b)return;const k=b.dataset.pgx;
 if(k==='save')pgxSave();else if(k==='share')pgxSave(true);else if(k==='close'){pgxClose();PGX_PEND=null}else if(k==='restore')pgxRestore();
 else if(k==='force'){pgxClose();pgxDl(new Blob([JSON.stringify(pgxBuild())],{type:'application/json'}),pgxName())}
 else if(k==='snooze'){try{localStorage.setItem(pgxKey()+':sn',String(Date.now()+864e5))}catch(e){}const x=b.closest('.pgx-bar');if(x)x.remove()}});
document.addEventListener('change',e=>{const t=e.target;if(t&&t.matches&&t.matches('[data-pgxin]'))pgxRead(t)});
window.pgxPlace=pgxPlace;
setTimeout(()=>{try{window.lfMount()}catch(e){}},0);

