 x.fillStyle='#FFF6F7';x.fillRect(0,0,W,H);const g=x.createLinearGradient(0,0,W,0);g.addColorStop(0,'#FF7A7A');g.addColorStop(1,'#E31414');x.fillStyle=g;x.fillRect(0,0,W,120);x.fillStyle='#fff';x.font=`800 52px ${FN}`;x.fillText('แฟ้มค้นหาตัวเอง',60,78);x.textAlign='right';x.font=`700 30px ${FN}`;x.fillText('ชีวิตที่ฉันเลือก',W-60,76);x.textAlign='left';
